registry_model = env['x_hr.recruitment_document'].sudo()
sign_template_model = env['sign.template'].sudo()
sign_document_model = env['sign.document'].sudo()
sign_item_model = env['sign.item'].sudo()
sign_role_model = env['sign.item.role'].sudo()
sign_send_model = env['sign.send.request'].sudo()
sign_send_signer_model = env['sign.send.request.signer'].sudo()
sign_request_model = env['sign.request'].sudo()
partner_model = env['res.partner'].sudo()

signature_type = env.ref('sign.sign_item_type_signature', raise_if_not_found=False)

applicant_role = (
    sign_role_model.search([('name', '=', 'Applicant')], order='id asc', limit=1)
    or sign_role_model.search([('name', '=', 'Employee')], order='id asc', limit=1)
    or sign_role_model.search([('name', '=', 'Customer')], order='id asc', limit=1)
    or sign_role_model.search([('name', '=', 'Signatory')], order='id asc', limit=1)
    or sign_role_model.search([], order='id asc', limit=1)
)

setup_error = False
if not signature_type:
    setup_error = 'Odoo Sign signature field type could not be found: sign.sign_item_type_signature.'
elif not applicant_role:
    setup_error = 'No Odoo Sign signer role was found. Create an Applicant, Employee, Customer, or Signatory role before sending F-0004.'

action = False

for rec in records.sudo():
    if setup_error:
        action = {
            'type': 'ir.actions.client',
            'tag': 'display_notification',
            'params': {
                'title': 'إعداد توقيع أودو غير مكتمل',
                'message': setup_error,
                'type': 'warning',
                'sticky': True,
            }
        }
        continue

    if rec.x_declaration_type != 'legal_documents_validity_declaration':
        action = {
            'type': 'ir.actions.client',
            'tag': 'display_notification',
            'params': {
                'title': 'نوع إقرار غير مدعوم',
                'message': 'الإرسال عبر توقيع أودو متاح حالياً فقط لإقرار F-0004.',
                'type': 'warning',
                'sticky': False,
            }
        }
        continue

    if rec.x_state == 'signed':
        action = {
            'type': 'ir.actions.client',
            'tag': 'display_notification',
            'params': {
                'title': 'F-0004 موقّع مسبقاً',
                'message': 'هذا الإقرار موقّع مسبقاً. لن يتم إنشاء طلب توقيع مكرر.',
                'type': 'warning',
                'sticky': False,
            }
        }
        continue

    if rec.x_state != 'generated' or not rec.x_pdf_attachment_id:
        action = {
            'type': 'ir.actions.client',
            'tag': 'display_notification',
            'params': {
                'title': 'F-0004 غير جاهز للإرسال',
                'message': 'أنشئ ملف F-0004 PDF قبل إرساله عبر توقيع أودو.',
                'type': 'warning',
                'sticky': False,
            }
        }
        continue

    applicant = rec.x_applicant_id
    if not applicant:
        action = {
            'type': 'ir.actions.client',
            'tag': 'display_notification',
            'params': {
                'title': 'لا يوجد متقدم',
                'message': 'لا يمكن إرسال F-0004 بدون متقدم مرتبط.',
                'type': 'warning',
                'sticky': True,
            }
        }
        continue

    applicant_name = applicant.partner_name or applicant.name or applicant.display_name
    applicant_email = applicant.email_from or False

    applicant_partner = False
    if 'partner_id' in applicant._fields and applicant.partner_id:
        applicant_partner = applicant.partner_id.sudo()

    if not applicant_partner and applicant_email:
        applicant_partner = partner_model.search([('email', '=', applicant_email)], order='id asc', limit=1)

    if not applicant_partner and applicant_email:
        applicant_partner = partner_model.create({
            'name': applicant_name or applicant_email,
            'email': applicant_email,
        })

    if not applicant_partner or not (applicant_partner.email or applicant_email):
        action = {
            'type': 'ir.actions.client',
            'tag': 'display_notification',
            'params': {
                'title': 'بريد المتقدم غير موجود',
                'message': 'أضف بريداً إلكترونياً للمتقدم قبل إرسال F-0004 عبر توقيع أودو.',
                'type': 'warning',
                'sticky': False,
            }
        }
        continue

    pdf_attachment = rec.x_pdf_attachment_id
    filename = pdf_attachment.name or ('%s - F-0004 Legal Documents Validity Declaration.pdf' % applicant_name)

    registry_doc = registry_model.search([
        ('x_document_type', '=', 'legal_documents_validity_declaration'),
        ('x_source_model', '=', 'x_hr.applicant_declaration'),
        ('x_source_res_id', '=', rec.id),
    ], order='id desc', limit=1)

    if not registry_doc:
        latest_any = registry_model.search([
            ('x_document_type', '=', 'legal_documents_validity_declaration'),
            ('x_applicant_id', '=', applicant.id),
        ], order='x_version desc, id desc', limit=1)

        next_version = (latest_any.x_version or 0) + 1 if latest_any else 1

        registry_doc = registry_model.create({
            'x_name': 'إقرار صحة المستندات - %s - v%s' % (applicant_name, next_version),
            'x_applicant_id': applicant.id,
            'x_document_type': 'legal_documents_validity_declaration',
            'x_state': 'generated',
            'x_generated_attachment_id': pdf_attachment.id,
            'x_version': next_version,
            'x_generated_on': rec.x_generated_on or datetime.datetime.now(),
            'x_responsible_user_id': env.user.id,
            'x_source_model': 'x_hr.applicant_declaration',
            'x_source_res_id': rec.id,
            'x_notes': 'تم استرداد سجل F-0004 في سجل مستندات التوظيف أثناء الإرسال عبر توقيع أودو.',
        })

    if registry_doc.x_state == 'signed':
        action = {
            'type': 'ir.actions.client',
            'tag': 'display_notification',
            'params': {
                'title': 'F-0004 موقّع مسبقاً',
                'message': 'سجل مستندات التوظيف لهذا الإقرار موقّع مسبقاً.',
                'type': 'warning',
                'sticky': False,
            }
        }
        continue

    if registry_doc.x_sign_request_res_id:
        existing_request = sign_request_model.browse(registry_doc.x_sign_request_res_id)
        if existing_request.exists():
            existing_state = existing_request.state or registry_doc.x_sign_request_state or 'unknown'
            if existing_state not in ['cancelled', 'canceled']:
                if existing_state == 'signed':
                    message = 'طلب توقيع أودو المرتبط موقّع بالفعل. استخدم مزامنة نتيجة التوقيع لإغلاق السجل.'
                else:
                    message = 'يوجد طلب توقيع أودو نشط لهذا الإقرار بحالة "%s". لن يتم إنشاء طلب مكرر.' % existing_state

                action = {
                    'type': 'ir.actions.client',
                    'tag': 'display_notification',
                    'params': {
                        'title': 'تم منع طلب توقيع مكرر',
                        'message': message,
                        'type': 'warning',
                        'sticky': True,
                    }
                }
                continue

    sent_on = datetime.datetime.now()
    validity_date = datetime.date.today() + datetime.timedelta(days=60)

    sign_template = sign_template_model.create({
        'name': filename,
        'user_id': env.user.id,
        'signature_request_validity': 60,
    })

    sign_document = sign_document_model.create({
        'template_id': sign_template.id,
        'attachment_id': pdf_attachment.id,
        'name': filename,
        'sequence': 1,
    })

    # F-0004 applicant-only Sign profile.
    # Coordinates measured from the generated one-page F-0004 PDF:
    # applicant signature blank cell, page 1, left/main signature area.
    sign_item_model.create({
        'document_id': sign_document.id,
        'type_id': signature_type.id,
        'responsible_id': applicant_role.id,
        'page': 1,
        'posX': 0.210,
        'posY': 0.570,
        'width': 0.360,
        'height': 0.056,
        'required': True,
        'name': 'Signature',
        'alignment': 'left',
        'constant': False,
    })

    subject = 'Signature Request - %s' % filename
    body = '<p>Please review and sign the attached F-0004 Legal Documents Validity Declaration.</p>'

    send_request = sign_send_model.create({
        'template_id': sign_template.id,
        'signer_id': applicant_partner.id,
        'subject': subject,
        'body': body,
        'validity': validity_date,
        'certificate_reference': False,
        'reminder_enabled': False,
        'model': 'x_hr.applicant_declaration',
        'res_ids': str([rec.id]),
    })

    if send_request.signer_ids:
        signer_line = send_request.signer_ids.filtered(lambda line: line.role_id.id == applicant_role.id)[:1]
        if not signer_line:
            signer_line = send_request.signer_ids[:1]
        signer_line.sudo().write({
            'partner_id': applicant_partner.id,
            'mail_sent_order': 1,
        })
    else:
        sign_send_signer_model.create({
            'sign_send_request_id': send_request.id,
            'role_id': applicant_role.id,
            'partner_id': applicant_partner.id,
            'mail_sent_order': 1,
        })

    send_request.send_request()

    generated_request = sign_request_model.search([
        ('template_id', '=', sign_template.id),
        ('request_item_ids.partner_id', '=', applicant_partner.id),
    ], order='create_date desc, id desc', limit=1)

    if generated_request:
        registry_doc.write({
            'x_state': 'signature_requested',
            'x_sent_on': sent_on,
            'x_responsible_user_id': env.user.id,
            'x_source_model': 'x_hr.applicant_declaration',
            'x_source_res_id': rec.id,
            'x_signature_mode': 'native_sign',
            'x_sign_request_model': 'sign.request',
            'x_sign_request_res_id': generated_request.id,
            'x_sign_request_reference': generated_request.reference or filename,
            'x_sign_request_state': generated_request.state or 'sent',
            'x_sign_request_url': '/odoo/sign/%s' % generated_request.id,
            'x_generated_attachment_id': pdf_attachment.id,
            'x_notes': ((registry_doc.x_notes or '') + '\\nNative Odoo Sign request created for F-0004 on %s. Request ID: %s. Applicant: %s.' % (sent_on, generated_request.id, applicant_partner.display_name)).strip(),
        })

        rec.write({
            'x_state': 'signature_requested',
            'x_sent_on': sent_on,
        })

        rec.message_post(body='تم إرسال F-0004 عبر توقيع أودو إلى %s.' % applicant_partner.display_name)
        applicant.message_post(body='تم إرسال إقرار F-0004 عبر توقيع أودو إلى %s.' % applicant_partner.display_name)

        action = {
            'type': 'ir.actions.client',
            'tag': 'display_notification',
            'params': {
                'title': 'تم إرسال F-0004 للتوقيع',
                'message': 'تم إنشاء طلب توقيع أودو وإرساله إلى %s.' % applicant_partner.display_name,
                'type': 'success',
                'sticky': False,
                'next': {'type': 'ir.actions.client', 'tag': 'reload'},
            }
        }
    else:
        registry_doc.write({
            'x_state': 'generated',
            'x_signature_mode': 'native_sign',
            'x_sign_request_model': 'sign.request',
            'x_sign_request_reference': filename,
            'x_sign_request_state': 'lookup_failed_after_send_request',
            'x_notes': ((registry_doc.x_notes or '') + '\\nNative Odoo Sign send_request() executed for F-0004 on %s, but the generated sign.request could not be located automatically. Dynamic template ID: %s.' % (sent_on, sign_template.id)).strip(),
        })

        action = {
            'type': 'ir.actions.client',
            'tag': 'display_notification',
            'params': {
                'title': 'تعذر العثور على طلب التوقيع',
                'message': 'تم تنفيذ الإرسال، لكن لم يتم العثور على sign.request تلقائياً. راجع تطبيق التوقيع قبل إعادة المحاولة.',
                'type': 'warning',
                'sticky': True,
            }
        }

    break

if not action:
    action = {'type': 'ir.actions.client', 'tag': 'reload'}

registry_model = env['x_hr.recruitment_document'].sudo()
sign_request_model = env['sign.request'].sudo()
action = False

for rec in records.sudo():
    applicant = rec.x_applicant_id

    if not applicant:
        action = {
            'type': 'ir.actions.client',
            'tag': 'display_notification',
            'params': {
                'title': 'لا يوجد متقدم',
                'message': 'لا يمكن مزامنة F-0004 بدون متقدم مرتبط.',
                'type': 'warning',
                'sticky': True,
            }
        }
        continue

    registry_doc = registry_model.search([
        ('x_document_type', '=', 'legal_documents_validity_declaration'),
        ('x_source_model', '=', 'x_hr.applicant_declaration'),
        ('x_source_res_id', '=', rec.id),
        ('x_signature_mode', '=', 'native_sign'),
        ('x_sign_request_res_id', '!=', False),
    ], order='id desc', limit=1)

    if not registry_doc:
        registry_doc = registry_model.search([
            ('x_document_type', '=', 'legal_documents_validity_declaration'),
            ('x_applicant_id', '=', applicant.id),
            ('x_signature_mode', '=', 'native_sign'),
            ('x_sign_request_res_id', '!=', False),
        ], order='id desc', limit=1)

    if not registry_doc:
        action = {
            'type': 'ir.actions.client',
            'tag': 'display_notification',
            'params': {
                'title': 'لا يوجد طلب توقيع مرتبط',
                'message': 'لم يتم العثور على سجل F-0004 مرتبط بطلب توقيع أودو.',
                'type': 'warning',
                'sticky': True,
            }
        }
        continue

    sign_request = sign_request_model.browse(registry_doc.x_sign_request_res_id)
    if not sign_request.exists():
        action = {
            'type': 'ir.actions.client',
            'tag': 'display_notification',
            'params': {
                'title': 'طلب التوقيع غير موجود',
                'message': 'طلب توقيع أودو المرتبط لم يعد موجوداً أو لا يمكن الوصول إليه.',
                'type': 'warning',
                'sticky': True,
            }
        }
        continue

    request_state = sign_request.state or 'unknown'

    registry_doc.write({
        'x_sign_request_state': request_state,
        'x_sign_request_reference': sign_request.reference or registry_doc.x_sign_request_reference,
    })

    if request_state != 'signed':
        rec.message_post(body='طلب توقيع F-0004 لم يكتمل بعد. حالة الطلب الحالية: %s.' % request_state)
        applicant.message_post(body='تم فحص حالة توقيع F-0004. الحالة الحالية: %s.' % request_state)

        action = {
            'type': 'ir.actions.client',
            'tag': 'display_notification',
            'params': {
                'title': 'F-0004 لم يكتمل توقيعه',
                'message': 'طلب توقيع أودو لا يزال بحالة: %s.' % request_state,
                'type': 'warning',
                'sticky': False,
            }
        }
        continue

    completed_attachments = sign_request.completed_document_attachment_ids

    # Robust attachment discovery:
    # Odoo Sign may expose the certificate and signed PDF differently depending on the
    # request/context. Never treat the certificate as the signed business document.
    related_attachments = env['ir.attachment'].sudo().search([
        ('res_model', '=', 'sign.request'),
        ('res_id', '=', sign_request.id),
        ('mimetype', '=', 'application/pdf'),
    ], order='create_date desc, id desc')

    all_completed_attachments = completed_attachments | related_attachments

    if not all_completed_attachments:
        registry_doc.write({
            'x_sign_request_state': 'signed_no_completed_attachment_found',
            'x_notes': ((registry_doc.x_notes or '') + '\\nOdoo Sign request %s is signed, but no completed document attachments were found during F-0004 sync on %s.' % (sign_request.id, datetime.datetime.now())).strip(),
        })

        action = {
            'type': 'ir.actions.client',
            'tag': 'display_notification',
            'params': {
                'title': 'المستند الموقع غير موجود',
                'message': 'طلب التوقيع موقّع، لكن لم يتم العثور على مرفقات المستند المكتمل.',
                'type': 'warning',
                'sticky': True,
            }
        }
        continue

    signed_native = False
    certificate_native = False

    for attachment in all_completed_attachments:
        attachment_name = (attachment.name or '').lower()
        is_certificate = (
            'certificate' in attachment_name
            or 'completion' in attachment_name
            or 'history' in attachment_name
            or 'audit' in attachment_name
            or 'شهادة' in attachment_name
        )

        if is_certificate:
            if not certificate_native:
                certificate_native = attachment
        elif not signed_native:
            signed_native = attachment

    if not signed_native:
        registry_doc.write({
            'x_sign_request_state': 'signed_no_business_document_found',
            'x_notes': ((registry_doc.x_notes or '') + '\\nOdoo Sign request %s is signed, but only certificate/history attachments were found during F-0004 sync on %s.' % (sign_request.id, datetime.datetime.now())).strip(),
        })

        action = {
            'type': 'ir.actions.client',
            'tag': 'display_notification',
            'params': {
                'title': 'المستند الموقع غير موجود',
                'message': 'تم العثور على شهادة التوقيع فقط، ولم يتم العثور على نسخة F-0004 الموقعة. افتح طلب التوقيع الأصلي وتحقق من المرفقات قبل إعادة المزامنة.',
                'type': 'warning',
                'sticky': True,
            }
        }
        continue

    signed_copy = registry_doc.x_signed_attachment_id

    # Do not trust a previously linked signed attachment blindly.
    # Earlier F-0004 test syncs could place the certificate in the signed-document field.
    # If the current signed attachment looks like a certificate/history file, move it into
    # the certificate path and replace the signed document from the actual signed business PDF.
    if signed_copy:
        signed_copy_name = (signed_copy.name or '').lower()
        signed_copy_is_certificate = (
            'certificate' in signed_copy_name
            or 'completion' in signed_copy_name
            or 'history' in signed_copy_name
            or 'audit' in signed_copy_name
            or 'شهادة' in signed_copy_name
        )

        if signed_copy_is_certificate:
            if not certificate_native:
                certificate_native = signed_copy
            signed_copy = False

    certificate_copy = registry_doc.x_sign_certificate_attachment_id

    if not certificate_copy and certificate_native:
        certificate_copy_name = certificate_native.name or ('Certificate of completion - F-0004 - %s.pdf' % (applicant.partner_name or applicant.name or applicant.display_name))

        if certificate_native.res_model == 'hr.applicant' and certificate_native.res_id == applicant.id:
            certificate_copy = certificate_native
        else:
            certificate_copy = certificate_native.copy({
                'name': certificate_copy_name,
                'res_model': 'hr.applicant',
                'res_id': applicant.id,
            })

    if not signed_copy:
        signed_copy = signed_native.copy({
            'name': signed_native.name or ('Signed F-0004 - %s.pdf' % (applicant.partner_name or applicant.name or applicant.display_name)),
            'res_model': 'hr.applicant',
            'res_id': applicant.id,
        })

    signed_on = False
    signer_items = sign_request.request_item_ids.filtered(lambda item: item.state == 'completed')
    for signer_item in signer_items:
        if signer_item.write_date and (not signed_on or signer_item.write_date > signed_on):
            signed_on = signer_item.write_date

    if not signed_on and sign_request.write_date:
        signed_on = sign_request.write_date

    if not signed_on and sign_request.completion_date:
        signed_on = datetime.datetime.combine(sign_request.completion_date, datetime.time(12, 0, 0))

    if not signed_on:
        signed_on = datetime.datetime.now()

    registry_values = {
        'x_state': 'signed',
        'x_signed_attachment_id': signed_copy.id,
        'x_sign_completed_attachment_id': signed_copy.id,
        'x_sign_completed_on': signed_on,
        'x_signed_on': signed_on,
        'x_sign_request_state': request_state,
        'x_sign_request_reference': sign_request.reference or registry_doc.x_sign_request_reference,
        'x_responsible_user_id': env.user.id,
        'x_source_model': 'x_hr.applicant_declaration',
        'x_source_res_id': rec.id,
        'x_notes': ((registry_doc.x_notes or '') + '\\nNative Odoo Sign completion synced for F-0004 on %s. Sign request ID: %s. Signed artifact: %s.' % (datetime.datetime.now(), sign_request.id, signed_copy.name)).strip(),
    }

    if not registry_doc.x_sent_on:
        registry_values['x_sent_on'] = rec.x_sent_on or sign_request.create_date or signed_on

    if certificate_copy:
        registry_values['x_sign_certificate_attachment_id'] = certificate_copy.id

    registry_doc.write(registry_values)

    rec.write({
        'x_state': 'signed',
        'x_signed_on': signed_on,
        'x_signed_attachment_id': signed_copy.id,
    })

    rec.message_post(
        body='تمت مزامنة توقيع F-0004 وربط المستند الموقع: %s.' % signed_copy.name,
        attachment_ids=[signed_copy.id],
    )

    applicant_attachment_ids = [signed_copy.id]
    if certificate_copy:
        applicant_attachment_ids.append(certificate_copy.id)

    applicant.message_post(
        body='تم توقيع إقرار F-0004 عبر توقيع أودو وربط المستند الموقع والشهادة، عند توفرها، بسجل مستندات التوظيف.',
        attachment_ids=applicant_attachment_ids,
    )

    action = {
        'type': 'ir.actions.client',
        'tag': 'display_notification',
        'params': {
            'title': 'تم توقيع F-0004',
            'message': 'تمت مزامنة نتيجة التوقيع وربط المستند الموقع والشهادة عند توفرها.',
            'type': 'success',
            'sticky': False,
            'next': {'type': 'ir.actions.client', 'tag': 'reload'},
        }
    }

    break

if not action:
    action = {'type': 'ir.actions.client', 'tag': 'reload'}

registry_model = env['x_hr.recruitment_document'].sudo()
action = False

for rec in records.sudo():
    registry_doc = registry_model.search([
        ('x_document_type', '=', 'legal_documents_validity_declaration'),
        ('x_source_model', '=', 'x_hr.applicant_declaration'),
        ('x_source_res_id', '=', rec.id),
        ('x_state', '=', 'signed'),
    ], order='id desc', limit=1)

    signed_attachment = rec.x_signed_attachment_id
    if registry_doc:
        signed_attachment = registry_doc.x_signed_attachment_id or registry_doc.x_sign_completed_attachment_id or signed_attachment

    if signed_attachment:
        signed_name = (signed_attachment.name or '').lower()
        looks_like_certificate = (
            'certificate' in signed_name
            or 'completion' in signed_name
            or 'history' in signed_name
            or 'audit' in signed_name
            or 'شهادة' in signed_name
        )

        if looks_like_certificate:
            action = {
                'type': 'ir.actions.client',
                'tag': 'display_notification',
                'params': {
                    'title': 'الملف الموقع غير صحيح',
                    'message': 'المرفق المرتبط كملف موقع يبدو أنه شهادة توقيع وليس نسخة F-0004 الموقعة. أعد تشغيل مزامنة نتيجة التوقيع لهذا الإقرار.',
                    'type': 'warning',
                    'sticky': True,
                }
            }
        else:
            action = {
                'type': 'ir.actions.act_url',
                'url': '/web/content/%s?download=true' % signed_attachment.id,
                'target': 'self',
            }
    else:
        action = {
            'type': 'ir.actions.client',
            'tag': 'display_notification',
            'params': {
                'title': 'لا يوجد ملف موقع',
                'message': 'لا يوجد ملف F-0004 موقع مرتبط بهذا الإقرار.',
                'type': 'warning',
                'sticky': False,
            }
        }
    break

if not action:
    action = {'type': 'ir.actions.client', 'tag': 'reload'}

registry_model = env['x_hr.recruitment_document'].sudo()
action = False

for rec in records.sudo():
    registry_doc = registry_model.search([
        ('x_document_type', '=', 'legal_documents_validity_declaration'),
        ('x_source_model', '=', 'x_hr.applicant_declaration'),
        ('x_source_res_id', '=', rec.id),
    ], order='id desc', limit=1)

    certificate_attachment = registry_doc.x_sign_certificate_attachment_id if registry_doc else False

    # Fallback for older bad test syncs where the certificate was accidentally linked
    # as the signed document before the separation logic was hardened.
    if not certificate_attachment:
        candidates = rec.x_signed_attachment_id
        if registry_doc:
            candidates = candidates | registry_doc.x_signed_attachment_id | registry_doc.x_sign_completed_attachment_id

        for attachment in candidates:
            attachment_name = (attachment.name or '').lower()
            looks_like_certificate = (
                'certificate' in attachment_name
                or 'completion' in attachment_name
                or 'history' in attachment_name
                or 'audit' in attachment_name
                or 'شهادة' in attachment_name
            )
            if looks_like_certificate:
                certificate_attachment = attachment
                break

    if certificate_attachment:
        action = {
            'type': 'ir.actions.act_url',
            'url': '/web/content/%s?download=true' % certificate_attachment.id,
            'target': 'self',
        }
    else:
        action = {
            'type': 'ir.actions.client',
            'tag': 'display_notification',
            'params': {
                'title': 'لا توجد شهادة توقيع',
                'message': 'لا توجد شهادة توقيع مرتبطة بهذا الإقرار حتى الآن.',
                'type': 'warning',
                'sticky': False,
            }
        }
    break

if not action:
    action = {'type': 'ir.actions.client', 'tag': 'reload'}
